import"./chunk-ZW5NV4UO.js";var e={fr:{title:"Polars et romans policiers sur Mastodon\xA0: qui suivre",description:"D\xE9couvre des lecteurs, des auteurs et des discussions autour du polar sur Mastodon. Explore les profils et les hashtags avant de cr\xE9er un compte.",heading:"Polars et romans policiers sur Mastodon",listTitle:"Polars et romans policiers",intro:["Une enqu\xEAte \xE0 r\xE9soudre, un roman noir \xE0 d\xE9couvrir ou une lecture \xE0 partager\xA0: retrouve des lecteurs, des auteurs et des librairies qui parlent de fiction polici\xE8re. Les recommandations et les \xE9changes autour des livres te donnent des pistes pour tes prochaines lectures.","Parcours les profils et les hashtags, lis quelques publications et choisis ce qui te pla\xEEt. Un compte peut aussi parler d\u2019autres sujets\xA0; les aper\xE7us te permettent de te faire une id\xE9e avant de le suivre."],faq:[{q:"Faut-il un compte pour lire\u202F?",a:"Non. Tu peux consulter cette page et les publications publiques sans compte. Pour suivre des profils ou des hashtags, connecte-toi avec un compte Mastodon."},{q:"Est-ce une s\xE9lection de faits divers\u202F?",a:"Cette s\xE9lection porte sur la fiction\xA0: romans policiers, enqu\xEAtes imaginaires et romans noirs. Certains comptes abordent aussi des affaires r\xE9elles ou d\u2019autres lectures."},{q:"Comment appara\xEEtre dans cette liste\u202F?",a:"Publie r\xE9guli\xE8rement sur le polar et utilise des hashtags pertinents. Les profils doivent remplir les crit\xE8res d\u2019activit\xE9 et d\u2019inclusion du catalogue\xA0; un hashtag ne garantit pas une place."}]},en:{title:"Mystery and crime books on Mastodon: people and hashtags",description:"Find mystery and crime readers, authors and book discussions on Mastodon. Choose people and hashtags, then preview your next reading community.",heading:"Mystery and crime books on Mastodon",listTitle:"Mystery and crime",intro:["Find your next puzzling case and people to discuss it with. Explore mystery and crime fiction through reader recommendations, reviews and authors sharing their work, from cozy mysteries and detective novels to noir and crime thrillers.","Choose people and hashtags, then preview their posts before following. Useful genre tags remain available even when quiet. Accounts are selected for recurring book content and substantive author updates, not just a keyword in a profile."],faq:[{q:"Do I need an account?",a:"Browse and preview public posts without an account. Sign in with your Mastodon account to follow your selection or create a list."},{q:"Which kinds of books belong here?",a:"Mystery and crime fiction across subgenres: detective stories, cozy mysteries, police procedurals, noir, historical mysteries and crime thrillers. Reading, reviewing, translating and writing these books all count. True crime, current crime news and screen-only fandom are separate topics. Hashtags are open conversations, so preview them before choosing."},{q:"How do I get onto this list?",a:"Share mystery or crime book content regularly and allow your server to suggest your profile. Substantive updates about your own books qualify too; a genre in your bio alone does not. For help or removal, contact @mawkingbird@mastodon.social."}]},de:{title:"Krimis auf Mastodon: Menschen und Hashtags entdecken",description:"Entdecke Menschen, die Krimis lesen und schreiben. W\xE4hle Profile und Hashtags von Cosy Crime bis Noir und schau dir deinen Feed vorab an.",heading:"Krimis auf Mastodon",listTitle:"Krimis",intro:["Entdecke deinen n\xE4chsten spannenden Fall und Menschen, mit denen du dar\xFCber sprechen kannst. Hier findest du Lesetipps, Rezensionen und Einblicke ins Schreiben: von Cosy Crime und Detektivromanen bis zu Noir und Kriminalthrillern.","W\xE4hle Profile und Hashtags aus und schau dir die Beitr\xE4ge in der Vorschau an. Auch passende Hashtags mit wenigen oder noch gar keinen Beitr\xE4gen bleiben dabei. Entscheidend sind regelm\xE4\xDFige Beitr\xE4ge \xFCber Krimis und inhaltliche Einblicke in eigene B\xFCcher, nicht blo\xDF ein Schlagwort im Profil."],faq:[{q:"Brauche ich ein Konto?",a:"Du kannst die Auswahl und \xF6ffentliche Beitr\xE4ge ohne Konto ansehen. Melde dich mit deinem Mastodon-Konto an, um Profilen und Hashtags zu folgen oder eine Liste anzulegen."},{q:"Welche B\xFCcher geh\xF6ren dazu?",a:"Kriminalliteratur in ihren verschiedenen Formen: Detektivgeschichten, Cosy Crime, Polizeikrimis, Noir, historische Krimis und Kriminalthriller. Lesen, Rezensieren, \xDCbersetzen und Schreiben geh\xF6ren gleicherma\xDFen dazu. True Crime, aktuelle Kriminalnachrichten und reine Film- oder Serienbeitr\xE4ge sind andere Themen. Hashtags sind offene Gespr\xE4che. Schau deshalb vor dem Folgen in die Vorschau."},{q:"Wie komme ich auf diese Liste?",a:"Teile regelm\xE4\xDFig Beitr\xE4ge \xFCber Krimis und erlaube deinem Server, dein Profil vorzuschlagen. Inhaltliche Einblicke in eigene B\xFCcher z\xE4hlen ebenfalls; ein Schlagwort im Profil allein reicht nicht. F\xFCr Hilfe oder eine Entfernung kontaktiere @mawkingbird@mastodon.social."}]}};export{e as COPY};
